    def submit_order(self, order):
        system_log.debug(f"接到委托订单，order_id：{order.order_id!s}，代码：{order.symbol!s}，当前时间：{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')!s}")
        account = self.engine.get_account(order.asset.symbol)
        try:
            if order.is_final():
                system_log.debug('委托订单状态异常：%s，撤销委托' % order.status.value)
                return None
            elif is_stock(order.symbol):
                entrust_amount = order.amount
                if entrust_amount > 1000000:
                    strategy_log.warning(_('后端服务 委托数量大于可委托数量【1000000】股，撤销委托'))
                    order._status = OrderStatus.REJECTED
                    self.orders.append(order)
                    return None
                else:
                    self.orders.append(order)
                    self.open_orders.append((account, order))
                    return None
            else:
                self.orders.append(order)
        except BaseException:
            strategy_log.error('后端服务 委托订单处理异常，错误信息：%s' % get_traceback_message())
            return None
    def cancel_order(self, order):
        if self.account_type == 'PTRADE_INTERFACE':
            if self.broker.trade_account.node_type == '7' and order.status not in CAN_CANCEL_STATUS_ENUM + [OrderStatus.ACCEPTED_KCXP, OrderStatus.CONFIRMED_KCXP] or self.broker.trade_account.node_type != '7' and order.status not in CAN_CANCEL_STATUS_ENUM:
                strategy_log.warning(f'订单：{order.order_id!s}当前为非可撤单状态：{order.status.value!s}，撤单取消')
                return None
        elif self.account_type in ('PTRADE_FUTURE_INTERFACE', 'PTRADE_OPTION_INTERFACE', 'PTRADE_HKS_INTERFACE') and order.status not in CAN_CANCEL_STATUS_ENUM:
            strategy_log.warning(f'订单：{order.order_id!s}当前为非可撤单状态：{order.status.value!s}，撤单取消')
            return None
        self.pending_cancel_orders.append(order)
