    def order_tick(self, sid, amount, priceGear='1', limit_price=None):
        if self.account_type == 'PTRADE_INTERFACE':
            symbol = sid.replace('SS', 'XSHG').replace('SZ', 'XSHE')
            if symbol[:2] in CB_CODE_RULES:
                if symbol in self.all_cb_list:
                    if self.cb_order_flag is False:
                        strategy_log.error('账户无可转债交易权限，无法进行对应类型交易')
                        return None
                else:
                    strategy_log.error('可转债代码%s识别失败，无法进行可转债交易权限判断' % symbol)
                    return None
        if is_stock(sid):
            if amount > 0:
                entrust_direction = EntrustDirection.BUY
            else:
                entrust_direction = EntrustDirection.SELL
            if limit_price is not None:
                style = LimitOrder(float(limit_price))
            else:
                price_gear = int(priceGear)
                snp = self.engine.data_proxy.get_snapshot(sid)
                if not (snp and snp[sid]):
                    strategy_log.error('代码【%s】实时行情获取失败，委托取消' % sid)
                    return None
                else:
                    snp = snp[sid]
                    bid_grp = snp['bid_grp']
                    offer_grp = snp['offer_grp']
                    if price_gear > 0:
                        price_gear = [gear for gear in range(1, price_gear + 1)]
                        gear_price_list = [bid_grp.get(gear, [0.0, 0, 0])[0] for gear in price_gear if bid_grp.get(gear, [0.0, 0, 0])[0] > 0]
                        if len(gear_price_list) == 0:
                            entrust_price = offer_grp.get(1)[0]
                            strategy_log.warning(f'代码【{sid!s}】处于跌停状态，买入价格调整为卖1价，价格：{entrust_price!s}')
                        else:
                            entrust_price = min(gear_price_list)
                    elif price_gear < 0:
                        price_gear = [gear for gear in range(1, abs(price_gear) + 1)]
                        gear_price_list = [offer_grp.get(gear, [0.0, 0, 0])[0] for gear in price_gear if offer_grp.get(gear, [0.0, 0, 0])[0] > 0]
                        if len(gear_price_list) == 0:
                            entrust_price = bid_grp.get(1)[0]
                            strategy_log.warning(f'代码【{sid!s}】处于涨停状态，卖出价格调整为买1价，价格：{entrust_price!s}')
                        else:
                            entrust_price = max(gear_price_list)
                    else:
                        strategy_log.error('priceGear入参不能为0，委托取消')
                        return None
                    style = LimitOrder(entrust_price)
            order = Order.create_order(self.engine.instance().get_asset(sid), abs(amount), entrust_direction, style)
            account = self.engine.get_account(order.asset.symbol)
            self.orders.append(order)
            self.open_orders.append((account, order))
            return order.order_id
        else:
            strategy_log.warning(_('该接口仅支持股票下单'))
    def on_pre_before_trading_start(self, event):
        if holiday_sync_account == '0':
            if not self.engine.data_proxy.is_trading_date(datetime.datetime.now().date()):
                pass
            else:
                self.sync_account()
        self.business_date = datetime.datetime.now().date()
        if int(datetime.datetime.now().strftime('%Y%m%d%H%M')) < int(datetime.datetime.now().strftime('%Y%m%d') + AFTER_TRADING_TIME):
            self.before_trading_start = True
        else:
            self.before_trading_start = False
        self.handle_data = False
        if self.account_type == 'PTRADE_INTERFACE':
            self.cb_order_flag = cb_order_flag_handle(self.broker.trade_account, self.stock_account)
            self.all_cb_list = list(set(get_all_stocks('CB') + get_cb_list_handle('1')))
        for account, order in self.open_orders:
            order.active()
            self.engine.event_bus.publish_event(Event(EventEnum.ORDER_CREATION_PASS, account=account, order=order))
    def on_before_trading_start(self, event):
        if os.path.exists(SIM_TRADING_LIST_PATH):
            try:
                with FileLock(SIM_TRADING_LIST_PATH, mode='shared'):
                    df = FileIO(SIM_TRADING_LIST_PATH).read(return_type='dataframe', index_col=0, dtype=str)
                df = df[df.index == self.trade_id]
                strategy_type = df['strategyType'][0]
                if strategy_type in ('10', '22'):
                    ai_date_file_path = TRADE_DIR_PATH + '/ai_date.txt'
                    if os.path.exists(ai_date_file_path):
                        f = open(ai_date_file_path, 'r')
                        date = f.read()
                        if int(date) < int(datetime.datetime.now().strftime('%Y%m%d')):
                            strategy_log.warning('AI许可证已过期')
                            self.set_trade_stop_status()
                elif strategy_type == '16':
                    strategy_id = df['backtestContentId'][0]
                    error_dict, response = self.broker.trade_account.get_clsc_subscribe_info()
                    error_no = error_dict.get('error_no', -1)
                    error_info = error_dict.get('error_info', '')
                    if error_no != 0:
                        msg = '获取策略商城策略订阅信息失败，错误原因：%s' % error_info
                        strategy_log.error(msg)
                    elif len(response) == 0:
                        msg = '策略商城策略订阅信息应答为空'
                        strategy_log.error(msg)
                    else:
                        for strategy_info in response:
                            strategy_name = strategy_info.get('mark_strategy_id')
                            fund_account = strategy_info.get('fund_account')
                            end_date = strategy_info.get('end_date')
                            if strategy_name is None or fund_account is None or end_date is None:
                                strategy_log.error('本条策略订阅信息解析异常，策略信息详情：%s' % strategy_info)
                                continue
                            elif fund_account != self.user_id:
                                continue
                            elif strategy_name not in strategy_id:
                                continue
                            elif int(end_date) < int(datetime.datetime.now().strftime('%Y%m%d')):
                                strategy_log.warning('策略：%s已过订阅有效期，停止交易' % strategy_name)
                                self.set_trade_stop_status()
            except BaseException:
                error_message = get_traceback_message()
                system_log.error(error_message)
        dt = datetime.datetime.now()
        now_date = dt.date().strftime('%Y-%m-%d')
        now_time = dt.time().strftime('%H:%M:%S')
        if now_date not in self.on_before_trading_start_time:
            self.on_before_trading_start_time[now_date] = [now_time]
            return None
        else:
            self.on_before_trading_start_time[now_date].append(now_time)
    def on_pre_after_trading_end(self, event):
        for order in self.orders:
            if not order.is_final():
                order._status = OrderStatus.REJECTED
    def on_after_trading_end(self, event):
        self.before_trading_start = False
        for account, order in self.open_orders:
            order.mark_rejected(_('Order Rejected: {symbol} can not match. Market close.').format(symbol=order.symbol))
        else:
            self.close_orders = {}
            self.cancel_orders = {}
            self.pending_cancel_orders = []
            self.after_trading_orders = []
            self.on_order_response_list = []
            self.on_trade_response_list = []
            self.reconnect_flag = False
            return None
    def on_handle_data(self, event):
        return None
    def on_handle_tick(self, event):
        return None
    def entrust_callback_func(self, error_dict, response, order=None):
        if order is not None:
            if error_dict.get('error_no') == -99:
                order._status = OrderStatus.REJECTED
                return None
            elif error_dict.get('error_no') != 0:
                strategy_log.error(_('委托失败，错误原因：%s' % error_dict.get('error_info')))
                order._status = OrderStatus.REJECTED
                return None
            elif int(response.get('error_no', 0)) != 0:
                strategy_log.error(_('委托失败，错误原因：%s' % response.get('error_info')))
                order._status = OrderStatus.REJECTED
                return None
            else:
                order.set_entrust_no(response.get('entrust_no'))
                self.close_orders[str(order.entrust_reference)] = order
                self.on_order_response_list_handle(order)
                self.on_trade_response_list_handle(order)
    def cancel_callback_func(self, error_dict, response, order=None):
        if error_dict.get('error_no') == 151159:
            strategy_log.warning(_('委托未生效，订单不可撤销'))
            return None
        elif error_dict.get('error_no') != 0:
            if self.business_type == 'stock':
                strategy_log.error(_('调用security_withdraw方法失败，error_info：%s' % error_dict.get('error_info')))
                return None
            elif self.business_type == 'rzrq':
                strategy_log.error(_('调用func_secu_rzrq_entrust_withdraw方法失败，error_info：%s' % error_dict.get('error_info')))
                return None
            elif self.business_type == 'hks':
                strategy_log.error(_('调用hks_entrust_withdraw方法失败，error_info：%s' % error_dict.get('error_info')))
                return None
            else:
                return None
        else:
            self.cancel_orders[str(response.get('entrust_no'))] = order
            order.set_cancel_entrust_no(str(response.get('entrust_no')))
            self.on_order_response_list_handle()
            self.on_trade_response_list_handle()
    def _process_order(self, engine):
        engine.set_engine(engine)
        while True:
            if len(self.open_orders) > 0:
                pass
            else:
                time.sleep(0.001)
                continue
            try:
                self.lock.acquire()
                account, order = self.open_orders.pop(0)
            finally:
                self.lock.release()
            if self.trade_status in (TRADE_STOP, TRADE_DELETE):
                system_log.debug('交易状态异常：%s，撤销委托' % self.trade_status)
                continue
            try:
                amount = order._amount
                if self.account_type == 'PTRADE_INTERFACE' and order.symbol[:2] in CB_CODE_RULES:
                    if order.symbol in self.all_cb_list:
                        if self.cb_order_flag is False:
                            strategy_log.error('账户无可转债交易权限，无法进行对应类型交易')
                            order._status = OrderStatus.REJECTED
                            continue
                        elif self.account_type in ('PTRADE_FUTURE_INTERFACE', 'PTRADE_OPTION_INTERFACE') and float(int(amount)) != float(amount):
                            strategy_log.error('委托失败，错误原因：期货、期权下单，委托数量必须为整数，order_id：%s' % order.order_id)
                            continue
                        else:
                            order._amount = int(amount)
                            error_dict, response = self.broker.process_order(order, engine, self.entrust_callback_func, strategyfare_id=self.strategyfare_id)
                            system_log.debug(f"订单委托结束，order_id：{order.order_id!s}，代码：{order.symbol!s}，当前时间：{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')!s}")
                            if error_dict.get('error_no') == -99:
                                strategy_log.error(_(f"委托失败，错误原因：{error_dict.get('error_info')!s}，order_id：{order.order_id!s}"))
                                order._status = OrderStatus.REJECTED
                                continue
                            elif error_dict.get('error_no') != 0:
                                strategy_log.error(_(f"委托失败，错误原因：{error_dict.get('error_info')!s}，order_id：{order.order_id!s}"))
                                order._status = OrderStatus.REJECTED
                                continue
                            else:
                                order_amount = order.amount
                                if is_stock(order.symbol):
                                    type_str = '股票'
                                    strategy_log('买入' if order.entrust_direction == EntrustDirection.BUY else '卖出')
                                elif order.symbol.split('.')[-1] in OPT_EXCHANGE_TYPES_DICT.keys():
                                    if order.futures_direction.value.upper() == 'EXECRISE':
                                        strategy_log.info('生成订单，订单号：{order_id}，合约代码：{symbol}，方向：卖出行权，数量：{share}手'.format(order_id=order.order_id, symbol=order.symbol, share=order.amount))
                                    else:
                                        strategy_log('生成订单，订单号：{order_id}，期权合约代码：{symbol}，方向：{side}{oper}，数量：{share}手, {hedge_type}'.format, order.order_id, order.symbol, '买入' if order.entrust_direction.value.upper() == 'BUY' else '卖出')
                                        '开仓' if order.futures_direction.value.upper() == 'OPEN' else '平仓'
                                        '非备兑类型委托' if order.hedge_type.value.upper() == 'SPECULATION' else '备兑类型委托'
                                else:
                                    strategy_log('生成订单，订单号：{order_id}，期货合约代码：{symbol}，方向：{side}{oper}，数量：{share}手'.format, order.order_id, order.symbol, '买入' if order.entrust_direction.value.upper() == 'BUY' else '卖出')
                                    '开仓' if order.futures_direction.value.upper() == 'OPEN' else '平仓'
                                    order.set_entrust_no(response.get('entrust_no'))
                                    self.close_orders[str(order.entrust_reference)] = order
                                    self.on_order_response_list_handle(order)
                                    self.on_trade_response_list_handle(order)
                                    self.engine.event_bus.publish_event(Event(EventEnum.SECURITY_ENTRUST, order=order))
                    else:
                        strategy_log.error('可转债代码%s识别失败，无法进行可转债交易权限判断' % order.symbol)
                        continue
            except BaseException:
                strategy_log.error('后端服务 委托失败，错误信息：%s' % get_traceback_message())
    def _process_tick_order(self, engine):
        engine.set_engine(engine)
        while True:
            while not self.before_trading_start:
                time.sleep(60)
            while self.before_trading_start:
                if len(self.open_orders) == 0:
                    continue
                try:
                    self.lock.acquire()
                    account, order = self.open_orders.pop(0)
                finally:
                    self.lock.release()
                if self.trade_status in (TRADE_STOP, TRADE_DELETE):
                    continue
                error_dict, response = self.broker.process_order(order, engine, False)
                if error_dict.get('error_no') == -99:
                    continue
                elif error_dict.get('error_no') != 0:
                    strategy_log.error(_('委托失败，错误原因：%s' % error_dict.get('error_info')))
                    continue
                strategy_log.info(_(f'【order_tick】: tick委托，信息订单号：{order.order_id!s} 股票代码：{order.symbol!s} 数量：{order.amount!s} 价格:{order.price!s}'))
                order.set_entrust_no(response['entrust_no'])
                self.close_orders[str(order.entrust_reference)] = order
                self.engine.event_bus.publish_event(Event(EventEnum.SECURITY_ENTRUST, order=order))
                time.sleep(0.001)
    def _process_cancel_order(self, engine):
        engine.set_engine(engine)
        while True:
            if len(self.pending_cancel_orders) > 0:
                pass
            else:
                time.sleep(0.001)
                continue
            try:
                self.lock.acquire()
                order = self.pending_cancel_orders.pop(0)
            finally:
                self.lock.release()
            if order in self.orders:
                entrust_no = order.entrust_no
                if entrust_no is None:
                    strategy_log.error(_('撤单失败，错误信息：订单委托失败'))
                    continue
                try:
                    if self.business_type == 'stock':
                        error_dict, response = self.broker.cancel_order(order, self.cancel_callback_func)
                    elif self.business_type == 'option':
                        error_dict, response = self.broker.option_cancel_order(order, self.cancel_callback_func)
                        if error_dict.get('error_no') == 0:
                            strategy_log.info(f'后端服务 操作账户代码:【{order.symbol!s}】 订单编号:【{order.order_id!s}】 委托号: 【{entrust_no!s}】 发起撤单')
                            if self.business_type == 'rzrq' and 'entrust_no_old' in response.keys():
                                self.cancel_orders[str(response.get('entrust_no_old'))] = order
                                order.set_cancel_entrust_no(str(response.get('entrust_no_old')))
                            else:
                                self.cancel_orders[str(response.get('entrust_no'))] = order
                                order.set_cancel_entrust_no(str(response.get('entrust_no')))
                            self.on_order_response_list_handle()
                            self.on_trade_response_list_handle()
                        elif error_dict.get('error_no') == T2SDK_RTNPACK_EMPTY:
                            if self.broker.trade_account.node_type == '7':
                                pass
                        strategy_log.error(_('后端服务 撤单失败，错误原因：%s' % error_dict.get('error_info')))
                    elif self.business_type == 'future':
                        error_dict, response = self.broker.future_cancel_order(order)
                    elif self.business_type == 'hks':
                        error_dict, response = self.broker.hks_cancel_order(order, self.cancel_callback_func)
                    elif self.business_type == 'rzrq':
                        error_dict, response = self.broker.rzrq_cancel_order(order)
                    else:
                        strategy_log.error('不支持的业务类型：%s' % self.business_type)
                        continue
                    if self.business_type in ('future', 'rzrq'):
                        self.cancel_orders[str(response.get('entrust_no_old'))] = order
                        order.set_cancel_entrust_no(str(response.get('entrust_no_old')))
                        self.cancel_orders[str(response.get('entrust_no'))] = order
                        order.set_cancel_entrust_no(str(response.get('entrust_no')))
                        self.on_order_response_list_handle()
                        self.on_trade_response_list_handle()
                        strategy_log.error(_('后端服务 撤单失败，错误原因：%s' % error_dict.get('error_info')))
                except BaseException:
                    strategy_log.error('后端服务 撤单失败，错误信息：%s' % get_traceback_message())
                continue
            strategy_log.error(_('当前订单状态不支持撤单'))
