    def scheme_order(self, strategy_no, strategy_param, scheme_stock_clob):
        """
        算法方案创建
        :return:
        """
        if self.broker.account_type == 'PBOX_PT_INTERFACE':
            if self.business_type == 'stock':
                if strategy_no not in ('1', '2', '100', 1, 2, 100):
                    strategy_log.error(_('不支持的策略编号[%s]，目前仅支持1-TWAP，2-VWAP。' % strategy_no))
                    return None
                elif not validate_strategy_params(strategy_param):
                    return None
                elif not validate_scheme_stock_clob(scheme_stock_clob):
                    return None
                else:
                    strategy_param_str = change_strategy_params(strategy_param)
                    kwargs = {'strategy_no': str(strategy_no), 'strategy_param': strategy_param_str, 'scheme_stock_clob': scheme_stock_clob}
                    error_dict, response = self.broker.trade_account.scheme_order(**(kwargs))
                    if error_dict.get('error_no') != 0:
                        strategy_log.error(_('调用scheme_order失败，失败信息[%s]' % error_dict.get('error_info')))
                        return None
                    else:
                        strategy_log.info(_('调用scheme_order成功，result[%s]' % response))
                        for stock in scheme_stock_clob:
                            schemedetail_info = dict()
                            schemedetail_info['scheme_no'] = response.get('scheme_no')
                            schemedetail_info['scheme_status'] = response.get('scheme_status')
                            schemedetail_info['strategy_no'] = str(strategy_no)
                            schemedetail_info['strategy_param'] = strategy_param_str
                            schemedetail_info['scheme_code'] = stock.get('scheme_code')
                            schemedetail_info['exchange_type'] = stock.get('exchange_type')
                            schemedetail_info['report_amount'] = stock.get('report_amount')
                            schemedetail_info['ins_price'] = stock.get('ins_price')
                            schemedetail_info['entrust_bs'] = stock.get('entrust_bs')
                            for scheme in response.get('message_clob'):
                                if schemedetail_info['scheme_code'] == scheme.get('scheme_code'):
                                    schemedetail_info['schemedetail_no'] = scheme.get('schemedetail_no')
                                    schemedetail_info['schemedetail_status'] = scheme.get('schemedetail_status')
                            self.schemedetail_list.append(schemedetail_info)
                        else:
                            file_name = os.path.join(TRADE_DIR_PATH, 'result', self.trade_id, 'scheme_flag.txt')
                            with open(file_name, 'w') as f:
                                f.write('exist')
                        return response.get('scheme_no')
            else:
                strategy_log.warning(_('算法方案仅在股票交易模块可用'))
                return None
        else:
            strategy_log.warning(_('算法方案仅在PBOX专业版可用'))
