    def get_schemedetail_status(self, scheme_no, scheme_code):
        """
        获取算法状态
        :return:
        """
        if self.broker.account_type == 'PBOX_PT_INTERFACE':
            if self.business_type == 'stock':
                error_dict, response = self.broker.trade_account.get_schemesinfo(scheme_no=scheme_no)
                if error_dict.get('error_no') != 0:
                    strategy_log.error(_('后端服务账户方案明细信息查询失败:%s' % error_dict.get('error_info')))
                    return (None, None)
                else:
                    for item in response:
                        for scheme in self.schemedetail_list:
                            if item.get('scheme_no') == scheme.get('scheme_no'):
                                scheme['scheme_status'] = item.get('scheme_status')
                    error_dict, response = self.broker.trade_account.get_schemes_detail(scheme_no=scheme_no)
                    if error_dict.get('error_no') != 0:
                        strategy_log.error(_('后端服务账户方案明细信息查询失败:%s' % error_dict.get('error_info')))
                        return (None, None)
                    else:
                        for item in response:
                            for scheme in self.schemedetail_list:
                                if item.get('schemedetail_no') == scheme.get('schemedetail_no'):
                                    scheme['schemedetail_status'] = item.get('schemedetail_status')
                        for item in self.schemedetail_list:
                            if scheme_no == item.get('scheme_no') and scheme_code[0:6] == item.get('scheme_code'):
                                return (item.get('schemedetail_no'), item.get('schemedetail_status'))
                        else:
                            return (None, None)
            else:
                strategy_log.warning(_('算法方案仅在股票交易模块可用'))
                return None
        else:
            strategy_log.warning(_('算法方案仅在PBOX专业版可用'))
    def sync_account(self):
        if self.broker.inter_acc_type in ('STOCK', 'FUTURE', 'OPTION', 'HKS'):
            account = self.broker.create_sys_account(self.orders, self.after_trading_orders)
            if account is not None:
                self.engine.portfolio.accounts[self.broker.inter_acc_type].sync_account(account)
        elif self.broker.inter_acc_type == 'COMBINE':
            stock_account = self.broker.create_sys_account(self.orders, self.after_trading_orders)['STOCK']
            self.engine.portfolio.accounts['STOCK'].sync_account(stock_account)
            future_account = self.broker.create_sys_account(self.orders, self.after_trading_orders)['FUTURE']
            self.engine.portfolio.accounts['FUTURE'].sync_account(future_account)
        self.engine.event_bus.publish_event(Event(EventEnum.ACCOUNT_QUERY))
    def _sync_worker(self, engine):
        """
        同步线程
        """
        steps = self.engine.config.plugins.plugin_system_trade.account_sync_steps
        engine.set_engine(engine)
        if self.business_type == 'future':
            pre_before_trading = future_pre_before_trading
            post_after_trading = future_post_after_trading
        elif self.business_type == 'hks':
            pre_before_trading = hks_pre_before_trading
            post_after_trading = hks_post_after_trading
        else:
            pre_before_trading = stock_pre_before_trading
            post_after_trading = stock_post_after_trading
        while True:
            while int(datetime.datetime.now().strftime('%H%M')) < pre_before_trading:
                time.sleep(60)
                return int(datetime.datetime.now().strftime('%H%M')) >= int(post_after_trading)
                continue
                if holiday_sync_account == '0':
                    pass
                self.engine.data_proxy.is_trading_date(datetime.datetime.now().date())
                continue
            if holiday_sync_account == '0':
                if not self.engine.data_proxy.is_trading_date(datetime.datetime.now().date()):
                    pass
            if self.engine.data_proxy.is_trading_date(datetime.datetime.now().date()) and self.reconnect_flag is False:
                if datetime.datetime.now().date() == self.first_run_date:
                    if (self.first_run_time < 900 or datetime.datetime.now().date() != self.first_run_date) and int(datetime.datetime.now().strftime('%H%M')) >= 900:
                        system_log.debug('后端服务操作账户开始执行自动重登录')
                        if not reconnect(self.broker.trade_account, self.trade_id):
                            break
                        self.reconnect_flag = True
            while pre_before_trading <= int(datetime.datetime.now().strftime('%H%M')) < int(post_after_trading):
                sync_data_flag = 0
                with self.order_or_trade_lock:
                    if self.receive_order_response_flag == 1 or self.receive_trade_response_flag == 1:
                        sync_data_flag = 1
                        self.receive_order_response_flag = 0
                        self.receive_trade_response_flag = 0
                sync_data_flag = 1
                if sync_data_flag:
                    self.sync_account()
                    self.sync_account_time = datetime.datetime.now()
                if len(self.on_order_response_list) > 0:
                    on_order_response_handle(self.on_order_response_list)
                if len(self.on_trade_response_list) > 0:
                    on_trade_response_handle(self.on_trade_response_list)
                time.sleep(steps)
                if pre_before_trading <= int(datetime.datetime.now().strftime('%H%M')):
                    pass
                time_difference = abs((datetime.datetime.now() - self.sync_account_time).total_seconds())
            time.sleep(steps)
    def _trade_status_handle(self, engine):
        """
        交易状态处理线程
        """
        engine.set_engine(engine)
        while True:
            self.trade_info = get_trade_status(self.trade_id, return_trade_info=True)
            trade_status = self.trade_info[2]
            if self.trade_status != trade_status:
                self.trade_status = trade_status
            else:
                time.sleep(0.5)
                continue
            self.engine.event_bus.publish_event(Event(EventEnum.SYSTEM_PAUSE))
            continue
            if trade_status == TRADE_STOP or trade_status == TRADE_DELETE:
                self.engine.event_bus.publish_event(Event(EventEnum.SYSTEM_TERMINATE))
                break
            if trade_status == TRADE_RELOAD:
                reload_info = self.get_reload_info()
                self.engine.event_bus.publish_event(Event(EventEnum.SYSTEM_RELOAD, **(reload_info)))
                trade_status = get_trade_status(self.trade_id)
                if trade_status == TRADE_RELOAD:
                    self.set_trade_running_status()
            else:
                self.engine.event_bus.publish_event(Event(EventEnum.SYSTEM_RESUME))
    def on_order_response(self, events):
        """
        处理交易系统委托主推
        :param events:
        :return:
        """
        self.engine.set_engine(self.engine)
        while len(events) > 0:
            with self.order_or_trade_lock:
                self.receive_order_response_flag = 1
            event = events.pop(0)
            system_log.debug('后端服务，接到委托主推：%s' % event)
            match_flag = False
            entrust_no = str(event.get('entrust_no'))
            try:
                receive_cancel_response = str(self.config.user.receive_cancel_response)
            except AttributeError:
                receive_cancel_response = '0'
            close_orders = self.close_orders.copy()
            cancel_orders = self.cancel_orders.copy()
            if 'entrust_reference' in event.keys() and event.get('entrust_reference') in list(close_orders.keys()):
                match_flag = True
                entrust_reference = event.pop('entrust_reference')
                if entrust_no in list(cancel_orders.keys()):
                    system_log.debug('后端服务，当前主推%s为撤单委托主推' % entrust_no)
                    if receive_cancel_response == '1':
                        system_log.debug('后端服务，策略配置为接收撤单主推%s' % entrust_no)
                        cancel_order = cancel_orders[entrust_no]
                        event['order_id'] = cancel_order.order_id
                        self.broker.entrust_rsp(event, cancel_order, True)
                    else:
                        system_log.debug('后端服务，策略配置为不接收撤单主推%s' % entrust_no)
                        break
                else:
                    system_log.debug('后端服务，当前主推%s为委托主推' % entrust_no)
                    order = close_orders[entrust_reference]
                    event['order_id'] = order.order_id
                    self.broker.entrust_rsp(event, order)
            elif entrust_no in list(cancel_orders.keys()):
                system_log.debug('后端服务，当前主推%s为撤单委托主推' % entrust_no)
                match_flag = True
                if receive_cancel_response == '1':
                    system_log.debug('后端服务，策略配置为接收撤单主推%s' % entrust_no)
                    cancel_order = cancel_orders[entrust_no]
                    event['order_id'] = cancel_order.order_id
                    self.broker.entrust_rsp(event, cancel_order, True)
                else:
                    system_log.debug('后端服务，策略配置为不接收撤单主推%s' % entrust_no)
                    break
                system_log.debug('后端服务，委托主推%s未匹配到对应Order' % entrust_no)
                if on_response_control == '1':
                    system_log.debug('后端服务，宿主机配置为策略接收非本交易触发的主推%s' % entrust_no)
                    event['order_id'] = ''
                    try:
                        receive_other_response = str(self.config.user.receive_other_response)
                    except AttributeError:
                        receive_other_response = '0'
                    if receive_other_response == '1':
                        system_log.debug('后端服务，策略配置为接收非本交易触发的主推%s' % entrust_no)
                        self.engine.event_bus.publish_event(Event(EventEnum.ON_ORDER_RSP, order=[event]))
                    else:
                        system_log.debug('后端服务，策略配置为不接收非本交易触发的主推%s' % entrust_no)
                        system_log.warning('丢弃未匹配的委托主推：%s' % event)
                else:
                    system_log.debug('后端服务，宿主机配置为策略不接收非本交易触发的主推%s' % entrust_no)
                    self.on_order_response_list.append(event)
            else:
                system_log.debug('后端服务，当前主推%s为委托主推' % entrust_no)
                for order in self.orders.copy():
                    if order.entrust_no == entrust_no and order.datetime.date() == self.business_date:
                        code = event.get('stock_code')
                        if 'XHKG' not in code:
                            stock_code = code.replace('SZ', 'XSHE').replace('SS', 'XSHG')
                        else:
                            stock_code = code
                        if stock_code.upper() == order.symbol.upper():
                            match_flag = True
                            system_log.debug('后端服务，委托主推%s匹配到对应Order' % entrust_no)
                            event['order_id'] = order.order_id
                            self.broker.entrust_rsp(event, order)
                            break
                        strategy_log.error(f'主推事件中的标的代码:{stock_code!s}与order对象中的标的代码:{order.symbol!s}不一致，导致委托主推失败')
            if not match_flag:
                pass
