    def marginsec_direct_refund(self, security, amount=None, cashgroup_prop=None):
        if self.trade_status in (TRADE_STOP, TRADE_DELETE):
            system_log.debug('直接还券接口:交易状态异常：%s，撤销委托' % self.trade_status)
            return None
        elif amount is None:
            strategy_log.warning('必须传入还券数量')
            return None
        elif cashgroup_prop is not None:
            cashgroup_prop = str(cashgroup_prop)
        else:
            cashgroup_prop = '1'
        margin_entrans_amount = self.get_margin_entrans_amount(security, cashgroup_prop=cashgroup_prop)
        if margin_entrans_amount is None:
            return None
        else:
            max_repay_stock_amount = float(margin_entrans_amount.get(security))
            if max_repay_stock_amount is None:
                return None
            elif amount > max_repay_stock_amount:
                strategy_log.warning(f'还款数量：{amount!s}超过最大可还数量：{max_repay_stock_amount!s}')
                return None
            elif security[0] == '6' or security[0] == '5':
                exchange_type = 1
            else:
                exchange_type = 2
            user_dict = {'exchange_type': exchange_type, 'stock_code': security.split('.')[0], 'entrust_amount': amount, 'cashgroup_prop': cashgroup_prop}
            error_dict, result = func_crdt_secu_return(self.broker.trade_account, **(user_dict))
            if error_dict.get('error_no') != 0:
                strategy_log.error('后端服务 现券还券失败:%s' % error_dict.get('error_info'))
                return None
            else:
                strategy_log.info('还券成功，还券数量：%s' % amount)
    def get_margin_contract(self, cashgroup_prop=None):
        if cashgroup_prop is not None:
            cashgroup_prop = str(cashgroup_prop)
        else:
            cashgroup_prop = '0'
        margin_contract_info = []
        for contract_type in ('0', '1'):
            user_dict = {'compact_type': contract_type, 'compact_source': cashgroup_prop}
            response = func_crdt_compact_get(self.broker.trade_account, **(user_dict))
            for contract in response:
                single_info = []
                for field in MARGIN_CONTRACT_FIELDS:
                    if field in contract.keys():
                        if field == 'stock_code':
                            exchange_type = contract.get('exchange_type')
                            code = contract.get(field)
                            if exchange_type:
                                if exchange_type == '1':
                                    code += '.SS'
                                elif exchange_type == '2':
                                    code += '.SZ'
                            elif code[0] == '6' or code[0] == '5':
                                code += '.SS'
                            elif code[0] == '3' or code[:3] == '002' or code[:3] == '000' or code[:2] == '15':
                                code += '.SZ'
                            single_info.append(code)
                            continue
                        single_info.append(contract.get(field))
                        continue
                    single_info.append(None)
                    continue
                margin_contract_info.append(single_info)
            if self.broker.trade_account.node_type == '6':
                break
        df = pd.DataFrame(columns=MARGIN_CONTRACT_FIELDS, data=margin_contract_info)
        if cashgroup_prop == '0':
            df['compact_source'] = '普通头寸'
        else:
            df['compact_source'] = '专项头寸'
        return df
