    def permission_test(self, account=None, end_date=None):
        if end_date is None:
            date_flag = True
        elif len(end_date) != 8:
            strategy_log.info('指定有效期时间格式不正确，请使用正确的格式：YYYYmmdd')
            return False
        else:
            today = datetime.datetime.now().strftime('%Y%m%d')
            if today <= end_date:
                date_flag = True
            else:
                date_flag = False
        if account is None:
            acount_flag = True
        else:
            self_acount = self.get_user_name()
            if account != self_acount:
                acount_flag = False
            else:
                acount_flag = True
        if date_flag and acount_flag:
            return True
        elif date_flag is False:
            strategy_log.info(_('有效期权限校验失败，请核实；指定有效期为：%s' % end_date))
            return False
        else:
            strategy_log.info(_('账户权限校验失败，请核实；指定账户为：%s' % account))
            return False
    def get_sort_msg(self, sort_type_grp=None, sort_field_name=None, sort_type=1, data_count=100):
        if isinstance(sort_type_grp, list):
            sort_type_str = ';'.join(sort_type_grp)
        elif isinstance(sort_type_grp, str):
            sort_type_str = sort_type_grp
        if 'XBHS.' not in sort_type_str:
            strategy_log.error('入参错误:sort_type_grp')
            return []
        elif not isinstance(sort_field_name, str):
            strategy_log.error('参数类型错误:sort_field_name')
            return []
        elif not isinstance(sort_type, int):
            strategy_log.error('参数类型错误:sort_type')
            return []
        elif not isinstance(data_count, int):
            strategy_log.error('参数类型错误:data_count')
            return []
        else:
            param = ['msg_sort', 'sort_type_grp=' + sort_type_str + ';', 'sort_field_name=' + sort_field_name, 'sort_type=' + str(sort_type), 'data_count=' + str(data_count)]
            redata = self.engine.data_proxy.api.entry.real_quote_handler.api_get_from_zeromq(str(param))
            count = 0
            while not redata and count < 3:
                time.sleep(1)
                if flag == 1:
                    strategy_log.debug('获取排序数据异常，现在进行第{}次重试'.format(str(count + 1)))
                elif flag == -1:
                    strategy_log.debug('获取排序数据返回为空，现在进行第{}次重试'.format(str(count + 1)))
                redata = self.engine.data_proxy.api.entry.real_quote_handler.api_get_from_zeromq(str(param))
                count += 1
        if flag == 1:
            strategy_log.debug('排序数据转化异常，默认返回空值')
        elif flag == -1:
            strategy_log.debug('排序数据返回空值')
        return redata
