    def get_covered_amount(self, code, lock_direction):
        userDict = {'query_flag': '1'}
        error_dict, result = func_fundaccount_qry(self.broker.trade_account, **(userDict))
        fund_account = ''
        fund_account_opt = ''
        if error_dict.get('error_no') != 0:
            strategy_log.error(_('获取现货账号失败，错误原因：%s' % error_dict.get('error_info')))
            return None
        elif len(result) < 2:
            strategy_log.error(_('获取现货账号异常，返回数据为：%s' % result))
            return None
        else:
            for data in result:
                if data['asset_prop'] == '0':
                    fund_account = data['fund_account']
                if data['asset_prop'] == 'B':
                    fund_account_opt = data['fund_account']
        if fund_account and fund_account_opt:
            userDict = {'stock_code': code.split('.')[0], 'fund_account': fund_account, 'fund_account_opt': fund_account_opt, 'lock_direction': lock_direction}
            error_dict, result = func_opt_covered_qry(self.broker.trade_account, **(userDict))
            if error_dict.get('error_no') != 0:
                if lock_direction == '1':
                    strategy_log.error(_(f"查询{code!s}标的备兑可锁定数量失败，错误原因：{error_dict.get('error_info')!s}"))
                    return None
                else:
                    strategy_log.error(_(f"查询{code!s}标的备兑可解锁数量失败，错误原因：{error_dict.get('error_info')!s}"))
                    return None
            elif result:
                return result[0]['enable_amount']
            else:
                return 0
        return None
    def option_covered_trans(self, code, amount, lock_direction):
        userDict = {'exchange_type': EXCHANGE_TYPES_DICT.get(code.split('.')[1])}
        option_account = ''
        error_dict, result = stock_account_query(self.broker.trade_account, **(userDict))
        if error_dict.get('error_no') != 0:
            strategy_log.error(_('获取option_account账号失败，错误原因：%s' % error_dict.get('error_info')))
            return None
        elif len(result) < 1:
            strategy_log.error(_('获取option_account账号异常，返回数据为：%s' % result))
            return None
        else:
            for data in result:
                option_account = data['stock_account']
        userDict = {'query_flag': '1'}
        fund_account = ''
        fund_account_opt = ''
        error_dict, result = func_fundaccount_qry(self.broker.trade_account, **(userDict))
        if error_dict.get('error_no') != 0:
            strategy_log.error(_('获取现货账号失败，错误原因：%s' % error_dict.get('error_info')))
            return None
        elif len(result) < 2:
            strategy_log.error(_('获取现货账号异常，返回数据为：%s' % result))
            return None
        else:
            for data in result:
                if data['asset_prop'] == '0':
                    fund_account = data['fund_account']
                if data['asset_prop'] == 'B':
                    fund_account_opt = data['fund_account']
        if option_account and fund_account and fund_account_opt:
            user_dict = {'stock_code': code.split('.')[0], 'fund_account': fund_account, 'asset_prop': 'B', 'fund_account_opt': fund_account_opt, 'entrust_amount': amount, 'lock_direction': lock_direction, 'exchange_type': EXCHANGE_TYPES_DICT.get(code.split('.')[1]), 'option_account': option_account}
            error_dict, result = opt_covered_trans(self.broker.trade_account, **(user_dict))
            if error_dict.get('error_no') != 0:
                if lock_direction == '1':
                    strategy_log.error(_(f"{code!s}标的备兑锁定失败，错误原因：{error_dict.get('error_info')!s}"))
                else:
                    strategy_log.error(_(f"{code!s}标的备兑解锁失败，错误原因：{error_dict.get('error_info')!s}"))
                return None
            elif lock_direction == '1':
                strategy_log.info(_(f'{code!s}标的备兑锁定成功，锁定数量：{amount!s}'))
            else:
                strategy_log.info(_(f'{code!s}标的备兑解锁成功，解锁数量：{amount!s}'))
            return None
        elif lock_direction == '1':
            strategy_log.error(_('%s标的备兑锁定失败，错误原因：期权账户获取失败' % code))
        else:
            strategy_log.error(_('%s标的备兑解锁失败，错误原因：期权账户获取失败' % code))
    def option_covered_lock(self, code, amount):
        return self.option_covered_trans(code, amount, '1')
    def option_covered_unlock(self, code, amount):
        return self.option_covered_trans(code, amount, '2')
    def get_hks_list(self, market='XHKG-SS;XHKG-SZ;'):
        if market.find('XHKG-SS') == -1 and market.find('XHKG-SZ') == -1:
            strategy_log.debug('请输入港股通市场:XHKG-SS、XHKG-SZ')
            return []
        current_time = datetime.datetime.now().strftime('%Y%m%d%H%M')
        if self.hks_list_time != current_time:
            param = ['stock_pool', 'XHKG-SS;XHKG-SZ;']
            redata = api_get_from_zeromq(str(param), user_log=system_log)
            count = 0
            while not redata and count < 3:
                time.sleep(1)
                if flag == 1:
                    strategy_log.debug('获取港股通代码，现在进行第{}次重试'.format(str(count + 1)))
                elif flag == -1:
                    strategy_log.debug('获取港股通代码为空，现在进行第{}次重试'.format(str(count + 1)))
                redata = self.engine.data_proxy.api.entry.real_quote_handler.api_get_from_zeromq(str(param), user_log=system_log)
                count += 1
            if flag == 1:
                strategy_log.debug('获取港股通代码异常，默认返回空值')
            elif flag == -1:
                strategy_log.debug('获取港股通代码返回空值')
            try:
                redata = redata['data']['stock_pool']
            except Exception:
                strategy_log.debug('获取港股通代码返回空值')
                redata = []
            self.hks_list = redata
        else:
            system_log.debug('get_hks_list同一分钟内多次调用，返回当前分钟首次查询的缓存数据')
        if market == 'XHKG-SS':
            ss_hks_list = []
            for code in self.hks_list:
                if code.find('XHKG-SS') != -1:
                    ss_hks_list.append(code)
            else:
                return ss_hks_list
        elif market == 'XHKG-SZ':
            sz_hks_list = []
            for code in self.hks_list:
                if code.find('XHKG-SZ') != -1:
                    sz_hks_list.append(code)
            else:
                return sz_hks_list
        else:
            return self.hks_list
    def hks_order(self, security, amount, limit_price=None, style=None):
        if style is None:
            style = 'enhance_limit'
        elif style == '1':
            style = 'enhance_limit'
        elif style == '2':
            style = 'at_auction_limit'
        else:
            strategy_log.warning("港股通委托方式style入参不符合要求，必须是'1'或'2' ")
            return None
        if style == 'enhance_limit':
            return self.hks_base_order(security, amount, limit_price=limit_price, entrust_prop='HKN', max_price_levels=0)
        elif style == 'at_auction_limit':
            return self.hks_base_order(security, amount, limit_price=limit_price, entrust_prop='HKN', max_price_levels=1)
    def hks_odd_lot_order(self, security, amount, limit_price=None):
        if amount > 0:
            strategy_log.warning('港股通零股交易只能做卖出')
            return None
        else:
            return self.hks_base_order(security, amount, limit_price=limit_price, entrust_prop='HKO', max_price_levels=0)
    def hks_base_order(self, security, amount, limit_price=None, entrust_prop=None, max_price_levels=None):
        if self.trade_status in (TRADE_STOP, TRADE_DELETE):
            system_log.debug('港股通交易接口:交易状态异常：%s，撤销委托' % self.trade_status)
            return None
        else:
            amount = int(amount)
            limit_price = protect_three_digit(limit_price)
            if limit_price is None:
                snp = self.engine.data_proxy.get_snapshot(security)
                if not (snp and snp[security]):
                    strategy_log.error('委托失败，原因：代码【%s】实时行情获取失败' % security)
                    return None
                else:
                    snp = snp[security]
                    entrust_price = snp.get('last_px', 0)
                    if entrust_price == 0:
                        strategy_log.error('委托失败，原因：代码【%s】实时行情获取失败' % security)
                        return None
                    else:
                        limit_price = float(entrust_price)
            if amount == 0:
                strategy_log.warning('股票委托数量为0, 委托取消')
                return None
            elif amount < 0:
                order_str = '卖出' + str(amount)
                entrust_direction = EntrustDirection.SELL
                entrust_bs = '2'
            else:
                order_str = '买入' + str(amount)
                entrust_direction = EntrustDirection.BUY
                entrust_bs = '1'
            order = Order.create_order(self.engine.instance().get_asset(security), abs(amount), entrust_direction, LimitOrder(limit_price))
            self.orders.append(order)
            try:
                exchange_type = EXCHANGE_TYPES_DICT.get(security.split('.')[1])
                if amount >= 0:
                    kwargs = {'exchange_type': exchange_type, 'entrust_bs': entrust_bs, 'business_type': 'hks', 'stock_code': security.split('.')[0], 'entrust_prop': entrust_prop, 'entrust_price': limit_price, 'max_price_levels': max_price_levels}
                else:
                    kwargs = {'exchange_type': exchange_type, 'business_type': 'hks', 'entrust_bs': entrust_bs, 'stock_code': security.split('.')[0], 'entrust_prop': entrust_prop, 'entrust_price': limit_price, 'max_price_levels': max_price_levels}
                kwargs['entrust_amount'] = abs(amount)
                error_dict, response = func_hks_security_entrust(self.broker.trade_account, **(kwargs))
                system_log.debug(f"订单委托结束，order_id：{order.order_id!s}，代码：{order.symbol!s}，当前时间：{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')!s}")
                if error_dict.get('error_no') != 0:
                    strategy_log.error(_(f"委托失败，错误原因：{error_dict.get('error_info')!s}，order_id：{order.order_id!s}"))
                    order._status = OrderStatus.REJECTED
                else:
                    strategy_log.info(f'生成订单，订单号：{str(order.order_id)!s}，港股通，股票代码：{security!s}，数量：{order_str!s}股')
                    order.set_entrust_no(str(response[0]['entrust_no']))
                    self.close_orders[str(order.entrust_reference)] = order
                    self.on_order_response_list_handle(order)
                    self.on_trade_response_list_handle(order)
                return order.order_id
            except BaseException:
                strategy_log.error('后端服务 委托失败，错误信息：%s' % get_traceback_message())
                return None
    def get_hks_price_gap(self):
        out_info = func_hks_price_gap_query(self.broker.trade_account)
        return out_info
    def get_hks_unit_amount(self, security, trade_type):
        out_info = {}
        if isinstance(security, list):
            for stock in security:
                exchange_type = EXCHANGE_TYPES_DICT.get(stock.split('.')[1])
                if trade_type == '1':
                    entrust_prop = 'HKN'
                elif trade_type == '2':
                    entrust_prop = 'HKO'
                out_info[stock] = self.get_hks_code_enter(stock, exchange_type, entrust_prop)
        elif isinstance(security, str):
            stock = security
            exchange_type = EXCHANGE_TYPES_DICT.get(stock.split('.')[1])
            if trade_type == '1':
                entrust_prop = 'HKN'
            elif trade_type == '2':
                entrust_prop = 'HKO'
            out_info[stock] = self.get_hks_code_enter(stock, exchange_type, entrust_prop)
        return out_info
    def get_hks_code_enter(self, stock, exchange_type, entrust_prop):
        out_info = {}
        kwargs = {'exchange_type': exchange_type, 'stock_code': stock.split('.')[0], 'entrust_prop': entrust_prop}
        data = func_hks_code_enter(self.broker.trade_account, **(kwargs))
        if data:
            try:
                data = data[0]
                out_info = {'sell_unit_amount': float(data['sell_unit']), 'buy_unit_amount': float(data['buy_unit'])}
            except BaseException:
                system_log.error(get_traceback_message())
        else:
            pass
        return out_info
    def get_lucky_info(self, start_date, end_date):
        current_time = datetime.datetime.now().strftime('%Y%m%d%H%M')
        if self.lucky_update_time != current_time:
            self.lucky_update_time = current_time
            lucky_info_list = his_lucky_info_qry(self.broker.trade_account, start_date, end_date)
            result = []
            for lucky_info in lucky_info_list:
                data = dict()
                data['stock_code'] = f"{lucky_info.get('stock_code')!s}.{EXCHANGE_TYPE_ENUM[lucky_info.get('exchange_type')].replace('XSHE', 'SZ').replace('XSHG', 'SS')!s}"
                data['stock_name'] = lucky_info.get('stock_name')
                data['occur_amount'] = lucky_info.get('occur_amount')
                data['business_price'] = lucky_info.get('business_price')
                data['init_date'] = lucky_info.get('init_date')
                result.append(data)
            else:
                self.lucky_info = result
                return self.lucky_info
        else:
            return self.lucky_info
    def get_all_positions(self):
        return self.broker.position_list
    def send_email(self, send_email_info, get_email_info, smtp_code, info, path, subject):
        if SEND_EMAIL_TIMES_LIMIT == '0':
            return send_email(send_email_info, get_email_info, smtp_code, info, path, subject)
        else:
            current_time = datetime.datetime.now().strftime('%Y%m%d%H%M')
            if self.send_email_update_time != current_time:
                self.send_email_update_time = current_time
                return send_email(send_email_info, get_email_info, smtp_code, info, path, subject)
            else:
                strategy_log.error('本交易同一分钟内不允许重复发送邮件')
    def on_system_rebuild(self, events):
        os.execl(sys.executable, sys.executable, os.path.join(TRADE_DIR_PATH, 'result', self.trade_id, 'user_code.py'), '1')
    def fund_transfer(self, trans_direction, occur_balance, exchange_type='1'):
        """
        资金调拨
        :param trans_direction: 调拨方向
        :type trans_direction: str
        :param occur_balance: 发生金额
        :type occur_balance: float
        :param exchange_type: 交易类别
        :type exchange_type: str
        :return: 调拨是否成功
        :rtype: bool
        """
        if exchange_type not in ('1', '2'):
            strategy_log.error('不支持的交易类别：%s' % exchange_type)
            return False
        elif trans_direction not in ('0', '1'):
            strategy_log.error('不支持的调拨方向：%s' % trans_direction)
            return False
        elif self.business_type != 'stock':
            strategy_log.error('仅支持在股票交易中调用')
            return False
        else:
            kwargs = {'exchange_type': exchange_type, 'money_type': '0', 'occur_balance': occur_balance, 'trans_direction': trans_direction}
            error_dict, response = self.broker.trade_account.fund_transfer(**(kwargs))
            if error_dict.get('error_no') != 0:
                return f"{'转入' if trans_direction == '0' else '转出'}极速{'沪A' if exchange_type == '1' else '深A'}"
    def market_fund_transfer(self, exchange_type, occur_balance):
        """
        市场间资金调拨
        :param exchange_type: 交易类别
        :type exchange_type: str
        :param occur_balance: 发生金额
        :type occur_balance: float
        :return: 调拨是否成功
        :rtype: bool
        """
        if exchange_type not in ('1', '2'):
            strategy_log.error('不支持的交易类别：%s' % exchange_type)
            return False
        elif self.business_type != 'stock':
            strategy_log.error('仅支持在股票交易中调用')
            return False
        else:
            kwargs = {'exchange_type': exchange_type, 'money_type': '0', 'occur_balance': occur_balance, 'trans_direction': '0'}
            error_dict, response = self.broker.trade_account.market_fund_transfer(**(kwargs))
            if error_dict.get('error_no') != 0:
                return f"strategy_log转入{'沪A' if exchange_type == '1' else '深A'}"
    def get_manage_mark(self):
        error_dict, response = self.broker.trade_account.get_manage_mark()
        if error_dict.get('error_no') != 0:
            strategy_log.error('获取管理端备注失败，异常信息： %s' % error_dict.get('error_info'))
            return ''
        elif len(response) > 0:
            return response[0].get('remark', '')
        else:
            return ''
    def set_email_info(self, email_address, smtp_code, email_subject):
        """
        设置邮箱信息。
        :param email_address: 邮箱地址
        :type email_address: str
        :param smtp_code: SMTP授权码
        :type smtp_code: str
        :param email_subject: 邮件主题
        :type email_subject: str
        :return: 邮箱信息是否设置成功
        :rtype: bool
        """
        if not isinstance(email_address, str):
            strategy_log.error('邮箱地址输入类型(%s)错误' % type(email_address))
            return False
        elif not isinstance(smtp_code, str):
            strategy_log.error('邮箱授权码输入类型(%s)错误' % type(smtp_code))
            return False
        elif not isinstance(email_subject, str):
            strategy_log.error('邮件主题输入类型(%s)错误' % type(smtp_code))
            return False
        elif any((arg.strip() == '' for arg in (email_address, smtp_code, email_subject))):
            strategy_log.error('邮箱地址、邮箱授权码、邮件主题输入不能为空')
            return False
        else:
            self.email_address = email_address
            self.smtp_code = smtp_code
            self.email_subject = email_subject
            strategy_log.info('邮箱信息设置成功')
            return True
